svg.script:
(() => {
  "use strict";
  const NS = "http://www.w3.org/2000/svg";
  const CELL = 27, GAP = 12, RESULT_LEFT = 240, INPUT_LEFT = 705, BIT_Y = 370, LOST_EXTRA_GAP = 18;
  let value = 0xCA;
  let shift = 2;
  const byId = id => document.getElementById(id);
  const make = (type, attributes, text) => {
    const element = document.createElementNS(NS, type);
    for (const [name, entry] of Object.entries(attributes)) element.setAttribute(name, String(entry));
    if (text !== undefined) element.textContent = text;
    return element;
  };
  const bitWidth = n => n > 0 ? n * CELL + Math.floor((n - 1) / 4) * GAP : 0;
  function highlightText(textId, backgroundId, horizontalPadding = 8, verticalPadding = 5) {
    const rect = byId(backgroundId);
    const bbox = byId(textId).getBBox();
    rect.setAttribute("x", bbox.x - horizontalPadding);
    rect.setAttribute("y", bbox.y - verticalPadding);
    rect.setAttribute("width", bbox.width + 2 * horizontalPadding);
    rect.setAttribute("height", bbox.height + 2 * verticalPadding);
  }
  const updateHighlights = () => {
    const codePrefix = byId("code-result-prefix");
    byId("code-result").setAttribute("x", Number(codePrefix.getAttribute("x")) + codePrefix.getComputedTextLength() + 9);
    const mathPrefix = byId("math-prefix");
    byId("math-quotient").setAttribute("x", Number(mathPrefix.getAttribute("x")) + mathPrefix.getComputedTextLength() + 9);
    highlightText("code-result", "code-result-highlight");
    highlightText("math-quotient", "math-quotient-highlight", 6, 5);
    const q = byId("math-quotient");
    const rem = byId("math-remainder");
    rem.setAttribute("x", Number(q.getAttribute("x")) + q.getComputedTextLength() + 6);
  };
  const toHex = number => `0x${number.toString(16).toUpperCase().padStart(2, "0")}`;

  function renderInputBits(bits) {
    const container = byId("input-bits");
    container.replaceChildren();
    let gapOffset = 0;
    for (let i = 0; i < 8; i++) {
      if (i > 0 && (8 - i) % 4 === 0) gapOffset += GAP;
      const x = INPUT_LEFT + i * CELL + gapOffset + CELL / 2;
      const pos = 7 - i;
      const group = make("g", {
        class: "diagram-click-bit", role: "button", tabindex: "0", "data-bit": i,
        "aria-label": `Bit ${pos}: ${bits[i]}; klicken zum Umschalten`
      });
      group.appendChild(make("title", {}, `Bit ${pos} umschalten`));
      group.appendChild(make("rect", {x: x - 13, y: BIT_Y - 39, width: 26, height: 51, rx: 6, ry: 6}));
      group.appendChild(make("text", {
        x, y: BIT_Y, "text-anchor": "middle", class: "bit-text diagram-a"
      }, bits[i]));
      group.addEventListener("click", () => {
        value ^= (1 << pos);
        render();
      });
      group.addEventListener("keydown", evt => {
        if (evt.key === "Enter" || evt.key === " ") {
          evt.preventDefault();
          value ^= (1 << pos);
          render();
        }
      });
      container.appendChild(group);
    }
  }

  function renderResultBits(bits, shift) {
    const resultBits = shift === 0 ? bits : bits.slice(0, 8 - shift);
    const lostBits = shift === 0 ? "" : bits.slice(8 - shift);
    const resultString = "0".repeat(shift) + resultBits;
    const resultWidth = bitWidth(8);
    const lostWidth = bitWidth(shift);
    const separator = shift > 0 ? LOST_EXTRA_GAP : 0;
    const totalWidth = resultWidth + separator + lostWidth;
    const startX = RESULT_LEFT + Math.max(0, (340 - totalWidth) / 2);
    const container = byId("result-bits");
    container.replaceChildren();

    let gapOffset = 0;
    for (let i = 0; i < 8; i++) {
      if (i > 0 && (8 - i) % 4 === 0) gapOffset += GAP;
      const x = startX + i * CELL + gapOffset + CELL / 2;
      let clazz = "diagram-bit-old";
      if (i < shift) clazz = "diagram-bit-new";
      const bit = make("text", {x, y: BIT_Y, "text-anchor": "middle", class: `bit-text ${clazz}`}, resultString[i]);
      container.appendChild(bit);
    }

    gapOffset = 0;
    for (let i = 0; i < shift; i++) {
      if (i > 0 && (shift - i) % 4 === 0) gapOffset += GAP;
      const x = startX + resultWidth + separator + i * CELL + gapOffset + CELL / 2;
      const bit = make("text", {x, y: BIT_Y, "text-anchor": "middle", class: "bit-text diagram-bit-lost"}, lostBits[i]);
      container.appendChild(bit);
      container.appendChild(make("line", {
        x1: x - 10, x2: x + 10, y1: BIT_Y - 14, y2: BIT_Y - 14, class: "diagram-strike"
      }));
    }

    byId("result-heading").setAttribute("x", startX + totalWidth / 2);
    const hl = byId("byte-bits-highlight");
    hl.setAttribute("x", String(startX - 8));
    hl.setAttribute("width", String(resultWidth + 16));
  }

  function render() {
    const bits = value.toString(2).padStart(8, "0");
    const quotient = value >> shift;
    const divisor = 2 ** shift;
    const remainder = shift === 0 ? 0 : value % divisor;
    renderResultBits(bits, shift);
    renderInputBits(bits);
    byId("code-input").textContent = toHex(value);
    byId("code-shift").textContent = String(shift);
    byId("code-result").textContent = toHex(quotient);
    byId("shift-value").textContent = String(shift);
    byId("shift-control").setAttribute("aria-label", `Shift ${shift}. Klick erhöht, Shift-Klick verringert`);
    byId("math-input").textContent = String(value);
    byId("math-exponent").textContent = String(shift);
    byId("math-quotient").textContent = String(quotient);
    byId("math-remainder").textContent = ` Rest ${remainder}`;
    updateHighlights();
    const note = byId("math-note");
    note.textContent = shift === 0
      ? "Es wird nicht verschoben: Es geht kein Bit verloren und der Rest ist 0."
      : remainder === 0
        ? "Es gehen zwar Bits nach rechts hinaus, hier ist der Rest aber 0."
        : "Die rechts herausgeschobenen Bits bilden den Rest.";
  }

  const control = byId("shift-control");
  const changeShift = evt => {
    const amount = evt.shiftKey ? -1 : 1;
    shift = Math.max(0, Math.min(8, shift + amount));
    render();
  };
  control.addEventListener("click", changeShift);
  control.addEventListener("keydown", evt => {
    if (evt.key === "Enter" || evt.key === " ") {
      evt.preventDefault();
      changeShift(evt);
    }
  });
  render();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(updateHighlights);
})();
